import React, { useState } from "react";
import type { Cow } from "../types/cow";

interface VisitReportModalProps {
  cows: Cow[];
  onClose: () => void;
}

export const VisitReportModal: React.FC<VisitReportModalProps> = ({ cows, onClose }) => {
  // Dados calculados automaticamente do sistema
  const lactatingCount = cows.filter(c => c.situation === "L").length;
  const dryCount = cows.filter(c => c.situation === "S").length;
  const totalCows = lactatingCount + dryCount;
  const heifersCount = cows.filter(c => c.categoryGS === "Novilha" || (c.categoryGS && c.categoryGS.includes("Novilha"))).length;
  const calvesCount = cows.filter(c => c.categoryGS === "Bezerra" || (c.categoryGS && c.categoryGS.includes("Bezerra"))).length;

  // Estados do formulário editáveis
  const [producerName, setProducerName] = useState("");
  const [farmName, setFarmName] = useState("");
  const [city, setCity] = useState("");
  const [visitDate, setVisitDate] = useState(new Date().toISOString().split("T")[0]);
  const [startTime, setStartTime] = useState("08:00");
  const [endTime, setEndTime] = useState("12:00");
  
  // Dados produtivos editáveis (com sugestões pré-preenchidas)
  const [employees, setEmployees] = useState("2");
  const [totalProduction, setTotalProduction] = useState("");
  const [ccs, setCcs] = useState("");
  const [cpp, setCpp] = useState("");

  // Atividades Realizadas (Sim / Não / Obs)
  const [activities, setActivities] = useState([
    { task: "Coleta e Atualização de Dados Zootécnicos", status: "SIM", obs: "" },
    { task: "Manejo Reprodutivo do Rebanho", status: "SIM", obs: "" },
    { task: "Manejo Sanitário, Cria e Recria", status: "SIM", obs: "" },
    { task: "Gestão da Nutrição e Produção de Volumoso", status: "SIM", obs: "" },
    { task: "Gestão da Qualidade do Leite", status: "SIM", obs: "" },
    { task: "Coleta e Atualização de Dados Financeiros", status: "NÃO", obs: "" },
  ]);

  // Seções de Recomendações
  const [repRec, setRepRec] = useState("");
  const [sanRec, setSanRec] = useState("");
  const [nutRec, setNutRec] = useState("");
  const [milkRec, setMilkRec] = useState("");
  const [nextVisitDate, setNextVisitDate] = useState("");

  const handleActivityChange = (index: number, field: "status" | "obs", value: string) => {
    const updated = [...activities];
    updated[index][field] = value;
    setActivities(updated);
  };

  const handlePrintReport = () => {
    const printWindow = window.open("", "_blank");
    if (!printWindow) {
      alert("Por favor, permita pop-ups para gerar a impressão.");
      return;
    }

    const prodPerCowLact = totalProduction && lactatingCount > 0 ? (Number(totalProduction) / lactatingCount).toFixed(1) : "-";
    const prodPerTotalCows = totalProduction && totalCows > 0 ? (Number(totalProduction) / totalCows).toFixed(1) : "-";

    const htmlContent = `
      <!DOCTYPE html>
      <html lang="pt-BR">
      <head>
        <meta charset="UTF-8">
        <title>Relatório de Visita Técnica</title>
        <style>
          body { font-family: Arial, sans-serif; font-size: 11px; color: #333; margin: 20px; line-height: 1.3; }
          .header { display: flex; align-items: center; justify-content: space-between; border-bottom: 2px solid #065f46; padding-bottom: 10px; margin-bottom: 15px; }
          .logo { max-height: 50px; width: auto; object-fit: contain; }
          h2 { margin: 0; color: #065f46; font-size: 16px; text-align: center; flex: 1; }
          .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 15px; background: #f8fafc; padding: 10px; border: 1px solid #e2e8f0; border-radius: 6px; }
          .info-item { display: flex; gap: 5px; }
          .info-item strong { min-width: 70px; color: #1e293b; }
          table { width: 100%; border-collapse: collapse; margin-bottom: 15px; }
          th, td { border: 1px solid #cbd5e1; padding: 6px 8px; text-align: left; }
          th { background-color: #065f46; color: white; font-weight: bold; }
          .text-center { text-align: center; }
          .section-title { background-color: #e2e8f0; font-weight: bold; color: #0f172a; padding: 5px 8px; margin-top: 10px; border: 1px solid #cbd5e1; }
          .rec-box { border: 1px solid #cbd5e1; padding: 8px; min-height: 40px; margin-bottom: 10px; background: #fff; }
          .signatures { display: flex; justify-content: space-between; margin-top: 40px; text-align: center; }
          .sig-line { width: 40%; border-top: 1px solid #333; padding-top: 5px; margin: 0 auto; }
          @media print { @page { size: portrait; } }
        </style>
      </head>
      <body>
        <div class="header">
          <img src="data:image/png;base64," alt="Logo" class="logo" />
          <h2>RELATÓRIO DE VISITA TÉCNICA</h2>
        </div>

        <div class="info-grid">
          <div class="info-item"><strong>Produtor:</strong> ${producerName || "-"}</div>
          <div class="info-item"><strong>Fazenda:</strong> ${farmName || "-"}</div>
          <div class="info-item"><strong>Data:</strong> ${visitDate ? visitDate.split("-").reverse().join("/") : "-"}</div>
          <div class="info-item"><strong>Cidade:</strong> ${city || "-"}</div>
          <div class="info-item"><strong>Início:</strong> ${startTime || "-"}</div>
          <div class="info-item"><strong>Término:</strong> ${endTime || "-"}</div>
        </div>

        <div style="font-weight: bold; margin-bottom: 5px; color: #065f46;">Informações Zootécnicas (Dia da Visita):</div>
        <table>
          <thead>
            <tr>
              <th>Categoria</th>
              <th class="text-center">Cab</th>
              <th>Dados Produtivos</th>
              <th class="text-center">Qtd</th>
              <th>Qualidade / Índices</th>
              <th class="text-center">Valores</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>Vacas em lactação</td>
              <td class="text-center"><strong>${lactatingCount}</strong></td>
              <td>Nº Funcionários</td>
              <td class="text-center">${employees || "-"}</td>
              <td>CCS (Células Somáticas)</td>
              <td class="text-center">${ccs || "-"}</td>
            </tr>
            <tr>
              <td>Vacas secas</td>
              <td class="text-center"><strong>${dryCount}</strong></td>
              <td>Produção Total (L/dia)</td>
              <td class="text-center">${totalProduction || "-"}</td>
              <td>CPP (Cont. Padrão)</td>
              <td class="text-center">${cpp || "-"}</td>
            </tr>
            <tr>
              <td>Novilhas</td>
              <td class="text-center"><strong>${heifersCount}</strong></td>
              <td>Média L / Vaca Lactação</td>
              <td class="text-center">${prodPerCowLact} L</td>
              <td>L / Vaca Total</td>
              <td class="text-center">${prodPerTotalCows} L</td>
            </tr>
            <tr>
              <td>Bezerras</td>
              <td class="text-center"><strong>${calvesCount}</strong></td>
              <td>Total Rebanho (Cab)</td>
              <td class="text-center"><strong>${totalCows}</strong></td>
              <td>Próxima Visita</td>
              <td class="text-center"><strong>${nextVisitDate ? nextVisitDate.split("-").reverse().join("/") : "-"}</strong></td>
            </tr>
          </tbody>
        </table>

        <div style="font-weight: bold; margin-bottom: 5px; color: #065f46;">Atividades Realizadas na Visita:</div>
        <table>
          <thead>
            <tr>
              <th>Atividade</th>
              <th class="text-center" style="width: 60px;">Sim</th>
              <th class="text-center" style="width: 60px;">Não</th>
              <th>Observação</th>
            </tr>
          </thead>
          <tbody>
            ${activities.map(act => `
              <tr>
                <td>${act.task}</td>
                <td class="text-center">${act.status === "SIM" ? "<b>[X]</b>" : "[ ]"}</td>
                <td class="text-center">${act.status === "NÃO" ? "<b>[X]</b>" : "[ ]"}</td>
                <td>${act.obs || "-"}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>

        <div class="section-title">Manejo Reprodutivo e Recomendações:</div>
        <div class="rec-box">${repRec.replace(/\n/g, '<br>') || "Nenhuma observação informada."}</div>

        <div class="section-title">Manejo Sanitário, Cria e Recria:</div>
        <div class="rec-box">${sanRec.replace(/\n/g, '<br>') || "Nenhuma observação informada."}</div>

        <div class="section-title">Produção de Volumoso / Nutrição das Vacas:</div>
        <div class="rec-box">${nutRec.replace(/\n/g, '<br>') || "Nenhuma observação informada."}</div>

        <div class="section-title">Qualidade do Leite:</div>
        <div class="rec-box">${milkRec.replace(/\n/g, '<br>') || "Nenhuma observação informada."}</div>

        <div style="margin-top: 15px; font-weight: bold; color: #065f46; font-size: 12px;">
          DATA DA PRÓXIMA VISITA: ${nextVisitDate ? nextVisitDate.split("-").reverse().join("/") : "A definir"}
        </div>

        <div class="signatures">
          <div class="sig-line">Assinatura Produtor</div>
          <div class="sig-line">Técnico / Médico Veterinário</div>
        </div>
      </body>
      </html>
    `;

    printWindow.document.write(htmlContent);
    printWindow.document.close();
    printWindow.focus();
    setTimeout(() => {
      printWindow.print();
    }, 800);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4 overflow-y-auto">
      <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full max-h-[90vh] flex flex-col overflow-hidden animate-fadeIn">
        
        {/* Cabeçalho do Modal */}
        <div className="bg-emerald-800 text-white px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <span className="text-xl">📋</span>
            <h3 className="font-bold text-base">Relatório de Visita Técnica</h3>
          </div>
          <button 
            onClick={onClose}
            className="text-white hover:bg-emerald-700 p-1.5 rounded-lg transition-colors font-bold text-sm"
          >
            ✕ Fechar
          </button>
        </div>

        {/* Corpo do Modal (Formulário) */}
        <div className="p-6 overflow-y-auto space-y-6 text-xs">
          
          {/* Dados Gerais */}
          <div className="bg-gray-50 p-4 rounded-lg border border-gray-200 grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div>
              <label className="block font-bold text-gray-700 mb-1">Nome do Produtor</label>
              <input 
                type="text" 
                value={producerName} 
                onChange={e => setProducerName(e.target.value)} 
                placeholder="Ex: João da Silva"
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>
            <div>
              <label className="block font-bold text-gray-700 mb-1">Nome da Fazenda</label>
              <input 
                type="text" 
                value={farmName} 
                onChange={e => setFarmName(e.target.value)} 
                placeholder="Ex: Fazenda Boa Esperança"
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>
            <div>
              <label className="block font-bold text-gray-700 mb-1">Cidade / Município</label>
              <input 
                type="text" 
                value={city} 
                onChange={e => setCity(e.target.value)} 
                placeholder="Ex: Viçosa - MG"
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>
            <div>
              <label className="block font-bold text-gray-700 mb-1">Data da Visita</label>
              <input 
                type="date" 
                value={visitDate} 
                onChange={e => setVisitDate(e.target.value)} 
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>
            <div>
              <label className="block font-bold text-gray-700 mb-1">Horário de Início</label>
              <input 
                type="time" 
                value={startTime} 
                onChange={e => setStartTime(e.target.value)} 
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>
            <div>
              <label className="block font-bold text-gray-700 mb-1">Horário de Término</label>
              <input 
                type="time" 
                value={endTime} 
                onChange={e => setEndTime(e.target.value)} 
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>
          </div>

          {/* Dados Zootécnicos puxados do Sistema */}
          <div>
            <div className="flex items-center justify-between mb-2">
              <h4 className="font-bold text-emerald-900 text-sm">Dados Zootécnicos (Sincronizados do Rebanho)</h4>
              <span className="text-[11px] text-emerald-700 bg-emerald-50 px-2 py-0.5 rounded border border-emerald-200">
                ✨ Valores contados automaticamente do sistema
              </span>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 bg-emerald-50/50 p-4 rounded-lg border border-emerald-200">
              <div className="bg-white p-2.5 rounded border border-emerald-100 text-center">
                <span className="block text-gray-500 font-medium">Vacas em Lactação</span>
                <span className="text-lg font-bold text-emerald-800">{lactatingCount}</span>
              </div>
              <div className="bg-white p-2.5 rounded border border-emerald-100 text-center">
                <span className="block text-gray-500 font-medium">Vacas Secas</span>
                <span className="text-lg font-bold text-amber-700">{dryCount}</span>
              </div>
              <div className="bg-white p-2.5 rounded border border-emerald-100 text-center">
                <span className="block text-gray-500 font-medium">Novilhas</span>
                <span className="text-lg font-bold text-blue-700">{heifersCount}</span>
              </div>
              <div className="bg-white p-2.5 rounded border border-emerald-100 text-center">
                <span className="block text-gray-500 font-medium">Bezerras</span>
                <span className="text-lg font-bold text-purple-700">{calvesCount}</span>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mt-3">
              <div>
                <label className="block font-bold text-gray-700 mb-1">Nº de Funcionários</label>
                <input 
                  type="text" 
                  value={employees} 
                  onChange={e => setEmployees(e.target.value)} 
                  className="w-full border border-gray-300 rounded-lg p-2 bg-white"
                />
              </div>
              <div>
                <label className="block font-bold text-gray-700 mb-1">Produção Total (L/dia)</label>
                <input 
                  type="number" 
                  value={totalProduction} 
                  onChange={e => setTotalProduction(e.target.value)} 
                  placeholder="Ex: 450"
                  className="w-full border border-gray-300 rounded-lg p-2 bg-white"
                />
              </div>
              <div>
                <label className="block font-bold text-gray-700 mb-1">Próxima Visita</label>
                <input 
                  type="date" 
                  value={nextVisitDate} 
                  onChange={e => setNextVisitDate(e.target.value)} 
                  className="w-full border border-gray-300 rounded-lg p-2 bg-white"
                />
              </div>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mt-3">
              <div>
                <label className="block font-bold text-gray-700 mb-1">CCS (Contagem de Células Somáticas)</label>
                <input 
                  type="text" 
                  value={ccs} 
                  onChange={e => setCcs(e.target.value)} 
                  placeholder="Ex: 250.000"
                  className="w-full border border-gray-300 rounded-lg p-2 bg-white"
                />
              </div>
              <div>
                <label className="block font-bold text-gray-700 mb-1">CPP (Contagem Padrão de Ptores)</label>
                <input 
                  type="text" 
                  value={cpp} 
                  onChange={e => setCpp(e.target.value)} 
                  placeholder="Ex: 20.000"
                  className="w-full border border-gray-300 rounded-lg p-2 bg-white"
                />
              </div>
            </div>
          </div>

          {/* Atividades Realizadas */}
          <div>
            <h4 className="font-bold text-emerald-900 text-sm mb-2">Atividades Realizadas na Visita</h4>
            <div className="space-y-2">
              {activities.map((act, idx) => (
                <div key={idx} className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 bg-gray-50 p-2 rounded border border-gray-200">
                  <span className="flex-1 font-medium text-gray-800">{act.task}</span>
                  <div className="flex items-center gap-2">
                    <label className="flex items-center gap-1 cursor-pointer font-bold text-emerald-800">
                      <input 
                        type="radio" 
                        name={`act-${idx}`} 
                        checked={act.status === "SIM"} 
                        onChange={() => handleActivityChange(idx, "status", "SIM")}
                      /> Sim
                    </label>
                    <label className="flex items-center gap-1 cursor-pointer font-bold text-red-700">
                      <input 
                        type="radio" 
                        name={`act-${idx}`} 
                        checked={act.status === "NÃO"} 
                        onChange={() => handleActivityChange(idx, "status", "NÃO")}
                      /> Não
                    </label>
                  </div>
                  <input 
                    type="text" 
                    placeholder="Observação..." 
                    value={act.obs}
                    onChange={e => handleActivityChange(idx, "obs", e.target.value)}
                    className="flex-1 border border-gray-300 rounded px-2 py-1 bg-white"
                  />
                </div>
              ))}
            </div>
          </div>

          {/* Recomendações Técnicas */}
          <div className="space-y-3">
            <h4 className="font-bold text-emerald-900 text-sm">Recomendações Técnicas por Área</h4>
            
            <div>
              <label className="block font-medium text-gray-700 mb-1">Manejo Reprodutivo</label>
              <textarea 
                rows={2} 
                value={repRec} 
                onChange={e => setRepRec(e.target.value)} 
                placeholder="Orientações sobre IATF, protocolos, touros..."
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>

            <div>
              <label className="block font-medium text-gray-700 mb-1">Manejo Sanitário, Cria e Recria</label>
              <textarea 
                rows={2} 
                value={sanRec} 
                onChange={e => setSanRec(e.target.value)} 
                placeholder="Vacinações, controle de carrapatos, aleitamento..."
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>

            <div>
              <label className="block font-medium text-gray-700 mb-1">Produção de Volumoso / Nutrição</label>
              <textarea 
                rows={2} 
                value={nutRec} 
                onChange={e => setNutRec(e.target.value)} 
                placeholder="Silagem, pastagem, concentrado, sal mineral..."
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>

            <div>
              <label className="block font-medium text-gray-700 mb-1">Qualidade do Leite</label>
              <textarea 
                rows={2} 
                value={milkRec} 
                onChange={e => setMilkRec(e.target.value)} 
                placeholder="Linha de ordenha, higiene, pré/pós-dipping..."
                className="w-full border border-gray-300 rounded-lg p-2 bg-white"
              />
            </div>
          </div>

        </div>

        {/* Rodapé do Modal com Botão de Impressão */}
        <div className="bg-gray-100 px-6 py-3.5 border-t border-gray-200 flex items-center justify-between">
          <button 
            onClick={onClose}
            className="px-4 py-2 border border-gray-300 rounded-lg text-gray-700 bg-white hover:bg-gray-50 font-medium text-xs transition-colors"
          >
            Cancelar
          </button>
          
          <button 
            onClick={handlePrintReport}
            className="px-5 py-2.5 bg-emerald-700 hover:bg-emerald-800 text-white font-bold rounded-lg shadow transition-colors flex items-center gap-2 text-xs"
          >
            <span>🖨️ Imprimir / Gerar PDF da Visita</span>
          </button>
        </div>

      </div>
    </div>
  );
};